Spec:
Feature initials: Get the initials of a name
Entrypoint: POST /initials
- AC1: POST /initials returns the first letter of each word
- AC2: initials are uppercase even when the name is not
- AC3: a value that is not a string is rejected with 400

Change:
--- features/initials/index.ts
import { json, type Feature } from "../../shared/http.ts";

export function compute(value: string): string {
  return value.split(/\s+/).filter(Boolean).map((word) => word[0] ?? "").join("");
}

export const feature: Feature = {
  id: "initials",
  title: "Get the initials of a name",
  routes: [
    {
      method: "POST",
      path: "/initials",
      handle: async (request) => {
        const body = (await request.json().catch(() => null)) as { value?: unknown } | null;
        if (typeof body?.value !== "string") return json({ error: "value must be a string" }, 400);
        return json({ result: compute(body.value) });
      },
    },
  ],
};

--- features/initials/initials.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import { createApp } from "../../shared/http.ts";
import { MemoryStore } from "../../shared/storage.ts";
import { feature } from "../../features/initials/index.ts";

async function call(value: unknown): Promise<{ status: number; result: unknown }> {
  const app = createApp([feature], new MemoryStore());
  const response = await app(new Request("http://app.test/initials", { method: "POST", body: JSON.stringify({ value }), headers: { "content-type": "application/json" } }));
  const body = (await response.json()) as { result?: unknown };
  return { status: response.status, result: body.result };
}

test("AC1: POST /initials returns the first letter of each word", async () => {
  const { status, result } = await call("Ada Lovelace");
  assert.equal(status, 200);
  assert.deepEqual(result, "AL");
});

test("AC2: initials are uppercase even when the name is not", async () => {
  const { status, result } = await call("Grace Hopper");
  assert.equal(status, 200);
  assert.deepEqual(result, "GH");
});

test("AC3: a value that is not a string is rejected with 400", async () => {
  const { status } = await call(42);
  assert.equal(status, 400);
});

